class TaskInitial:
    def __init__(self, T_i, D_i, P_i, C_i_vec):
        self.T = T_i
        self.D = D_i
        self.P = P_i
        self.C_vec = C_i_vec # List of WCETs for different cache sizes

def get_hp_set(task_i, task_set):
    hp_set = []
    for task_j in task_set:
        if task_j.P > task_i.P:
            hp_set.append(task_j)
    return hp_set

def get_ht_set(task_i, task_set):
    ht_set = []
    for task_j in task_set:
        if task_j.P > task_i.pi:
            ht_set.append(task_j)
    return ht_set

def get_lp_blocking_set(task_i, task_set):
    lp_blocking_set = []
    for task_j in task_set:
        if task_j.P < task_i.P and task_i.P <= task_j.pi:
            lp_blocking_set.append(task_j)
    return lp_blocking_set

def is_task_set_schedulable(task_set):
    for task_i in task_set:
        if not is_task_schedulable(task_i, task_i.R): # Assuming R_i is already computed and stored
            return False
    return True

import math

def calculate_start_time(task_i, task_set, B_i, q, MAX_RESPONSE_TIME_BOUND=float('inf')):
    # C_i is task_i.C (C_i_k)
    hp_i_set = get_hp_set(task_i, task_set)

    S_i_q_current = B_i + q * task_i.C
    while True:
        S_i_q_next = B_i + q * task_i.C
        for task_j in hp_i_set:
            S_i_q_next += (1 + math.floor(S_i_q_current / task_j.T)) * task_j.C

        if S_i_q_next == S_i_q_current:
            return S_i_q_next
        elif S_i_q_next > MAX_RESPONSE_TIME_BOUND: # Prevent infinite loop
            return float('inf')
        S_i_q_current = S_i_q_next
